// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address ownerCandidate, uint256 withdrawAmount) internal {
        ownerCandidate = address(this);
        bool reverted;
        try c.withdraw(withdrawAmount) {} catch { return; }
        try c.withdraw(withdrawAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (c.owner() != ownerCandidate));
    }

    function testFuzz_run(address ownerCandidate, uint256 withdrawAmount) public {
        _run(ownerCandidate, withdrawAmount);
    }

    receive() external payable {}
}
